-- Beauty Feedback Table\n-- Stores user ratings and comments on beauty reports\n\nCREATE TABLE IF NOT EXISTS beauty_feedback (\n    id TEXT PRIMARY KEY DEFAULT uuidv(),\n    user_id TEXT,\n    report_id TEXT,\n    rating INTEGER CHECK(rating >= 1 AND rating <= 5),\n    comment TEXT,\n    created_at DATETIME DEFAULT CURRENT_TIMESTAMP);\n\nCREATE INDEX IF NOT EXISTS idx_beauty_feedback_user ON beauty_feedback(user_id);\nCREATE INDEX IF NOT EXISTS idx_beauty_feedback_report ON beauty_feedback(report_id);\nCREATE INDEX IF NOT EXISTS idx_beauty_feedback_created ON beauty_feedback(created_at);
